CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL DEFAULT '', avatar TEXT, is_temp INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), last_seen TIMESTAMPTZ, is_online INTEGER DEFAULT 0, is_typing INTEGER DEFAULT 0, typing_to INTEGER);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, original_name TEXT, filename TEXT, file_type TEXT, file_size BIGINT, upload_date TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS friends (id SERIAL PRIMARY KEY, from_user INTEGER REFERENCES users(id) ON DELETE CASCADE, to_user INTEGER REFERENCES users(id) ON DELETE CASCADE, status TEXT DEFAULT 'pending', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages (id SERIAL PRIMARY KEY, sender_id INTEGER REFERENCES users(id) ON DELETE CASCADE, receiver_id INTEGER REFERENCES users(id) ON DELETE CASCADE, message_text TEXT, file_name TEXT, file_type TEXT, file_path TEXT, file_size BIGINT DEFAULT 0, duration_seconds DOUBLE PRECISION, media_kind TEXT, is_read INTEGER DEFAULT 0, deleted_for_sender INTEGER DEFAULT 0, deleted_for_receiver INTEGER DEFAULT 0, forward_from TEXT, forward_from_name TEXT, is_self_destruct INTEGER DEFAULT 0, destruct_after_view INTEGER DEFAULT 0, reply_to INTEGER, reply_text TEXT, reply_sender TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS avatars (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, avatar_path TEXT, is_active INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS shared_pins (id SERIAL PRIMARY KEY, message_id INTEGER REFERENCES messages(id) ON DELETE CASCADE, chat_user1 INTEGER, chat_user2 INTEGER, pinned_by INTEGER REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS private_pins (id SERIAL PRIMARY KEY, message_id INTEGER REFERENCES messages(id) ON DELETE CASCADE, chat_user1 INTEGER, chat_user2 INTEGER, pinned_by INTEGER REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reactions (id SERIAL PRIMARY KEY, message_id INTEGER REFERENCES messages(id) ON DELETE CASCADE, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, reaction TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS file_access (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, granted_by INTEGER REFERENCES users(id) ON DELETE SET NULL, granted_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_messages_chat ON messages(sender_id, receiver_id, created_at);
CREATE INDEX IF NOT EXISTS idx_messages_receiver_read ON messages(receiver_id, is_read);
CREATE INDEX IF NOT EXISTS idx_friends_users ON friends(from_user, to_user, status);
CREATE INDEX IF NOT EXISTS idx_reactions_message ON reactions(message_id);
